def _chain_join(n):
    table = []
    for i in range(n):
        for j in range(n):
            table.append(i if i > j else j)
    return _make_int_op("v", 2, n, table)

def _chain_meet(n):
    table = []
    for i in range(n):
        for j in range(n):
            table.append(i if i < j else j)
    return _make_int_op("meet", 2, n, table)

def _bool_or(n):
    size = 1 << n
    table = []
    for i in range(size):
        for j in range(size):
            table.append(i | j)
    return _make_int_op("v", 2, size, table)

def _bool_and(n):
    size = 1 << n
    table = []
    for i in range(size):
        for j in range(size):
            table.append(i & j)
    return _make_int_op("meet", 2, size, table)

def _prod_max(n, m):
    size = n * m
    table = []
    for a in range(size):
        for b in range(size):
            ai, aj = a // m, a % m
            bi, bj = b // m, b % m
            ci = ai if ai > bi else bi
            cj = aj if aj > bj else bj
            table.append(ci * m + cj)
    return _make_int_op("v", 2, size, table)

